use std::collections::BTreeMap;
use std::io::{self, Read, Write};

struct Stats {
    count: u64,
    total: u128,
    actions: BTreeMap<String, u64>,
}

fn parse_seconds(s: &str) -> Option<u128> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse::<u128>().ok()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut users: BTreeMap<String, Stats> = BTreeMap::new();
    let mut malformed: u64 = 0;

    for line in input.lines() {
        let tokens: Vec<&str> = line.split_whitespace().collect();
        if tokens.len() != 3 {
            malformed += 1;
            continue;
        }
        let secs = match parse_seconds(tokens[2]) {
            Some(v) => v,
            None => {
                malformed += 1;
                continue;
            }
        };
        let stats = users.entry(tokens[0].to_string()).or_insert(Stats {
            count: 0,
            total: 0,
            actions: BTreeMap::new(),
        });
        stats.count += 1;
        stats.total += secs;
        *stats.actions.entry(tokens[1].to_string()).or_insert(0) += 1;
    }

    let mut rows: Vec<(String, Stats)> = users.into_iter().collect();
    rows.sort_by(|a, b| b.1.total.cmp(&a.1.total).then_with(|| a.0.cmp(&b.0)));

    let stdout = io::stdout();
    let mut out = stdout.lock();
    for (name, stats) in &rows {
        // BTreeMap iterates actions alphabetically, so the first maximum wins ties.
        let mut top: (&String, u64) = (&stats.actions.keys().next().unwrap(), 0);
        for (action, &n) in &stats.actions {
            if n > top.1 {
                top = (action, n);
            }
        }
        writeln!(out, "{} {} {} {}", name, stats.count, stats.total, top.0).unwrap();
    }
    writeln!(out, "malformed: {}", malformed).unwrap();
}
